<?php $v = fn($k) => $row[$k] ?? ''; $er = fn($k) => isset($errors[$k]) ? '<div class="err"><i class="bi bi-exclamation-circle"></i> ' . e($errors[$k]) . '</div>' : ''; ?>
<div class="page-head"><div><h1>Reportar un problema</h1><p>Cuéntanos qué ocurre y un técnico se pondrá en contacto contigo.</p></div></div>
<form method="post" class="form-ui" novalidate><?= csrf_field() ?><div class="card-ui" style="max-width:760px"><div class="row g-3">
  <div class="col-md-6"><label class="lbl">Categoría <span class="req">*</span></label><select class="form-select <?= isset($errors['categoria_id']) ? 'is-invalid' : '' ?>" name="categoria_id"><option value="">— Seleccionar —</option><?php foreach ($categorias as $c): ?><option value="<?= $c['id'] ?>" <?= (int)$v('categoria_id') === (int)$c['id'] ? 'selected' : '' ?>><?= e($c['nombre']) ?></option><?php endforeach; ?></select><?= $er('categoria_id') ?></div>
  <div class="col-md-6"><label class="lbl">¿Qué tan urgente es?</label><select class="form-select" name="prioridad"><?php foreach (['baja' => 'Baja · puede esperar', 'media' => 'Media · afecta mi trabajo', 'alta' => 'Alta · no puedo trabajar'] as $k => $l): ?><option value="<?= $k ?>" <?= $v('prioridad') === $k ? 'selected' : '' ?>><?= $l ?></option><?php endforeach; ?></select></div>
  <div class="col-12"><label class="lbl">Equipo afectado</label><select class="form-select" name="activo_id"><option value="">— No aplica / no sé —</option><?php foreach ($activos as $a): ?><option value="<?= $a['id'] ?>" <?= (int)$v('activo_id') === (int)$a['id'] ? 'selected' : '' ?>><?= e($a['codigo'] . ' · ' . $a['tipo'] . ' ' . $a['marca'] . ' ' . $a['modelo']) ?></option><?php endforeach; ?></select></div>
  <div class="col-12"><label class="lbl">Asunto <span class="req">*</span></label><input class="form-control <?= isset($errors['asunto']) ? 'is-invalid' : '' ?>" name="asunto" maxlength="180" value="<?= e($v('asunto')) ?>" placeholder="Ej: No puedo imprimir desde la oficina de contabilidad"><?= $er('asunto') ?></div>
  <div class="col-12"><label class="lbl">Detalle</label><textarea class="form-control" name="descripcion" rows="5" maxlength="3000" placeholder="¿Desde cuándo ocurre? ¿Aparece algún mensaje de error?"><?= e($v('descripcion')) ?></textarea></div>
  <div class="col-12 d-flex gap-2"><button class="btn btn-brand"><i class="bi bi-send me-1"></i>Enviar solicitud</button><a class="btn btn-ghost" href="<?= url('portal') ?>">Cancelar</a></div></div></div></form>
